-- M3 — Whitelist do trigger tg_movimentacoes_sync_estoque_lotes: 2 novos motivos
-- Corpo IDÊNTICO ao vigente (verificado ao vivo); única mudança: +2 motivos PDV.
CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.motivo,'') NOT IN (
       'scanner_lote', 'contagem_caixa', 'ajuste_lote_manual',
       'saida_inteira', 'retirada_avulsa', 'adicao_avulsa',
       'saida_inteira_exposicao', 'retirada_avulsa_exposicao',
       'saida_requisicao',
       'entrada_requisicao',
       'entrada_pdv_externo',
       'saida_pdv_externo'
     ) THEN
    RETURN NEW;
  END IF;

  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('app.skip_lote_reconcile', '1', true);

  IF NEW.tipo_movimentacao = 'entrada' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;
  ELSIF NEW.tipo_movimentacao = 'saida' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;
  END IF;

  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
  END IF;

  RETURN NEW;
END;
$function$;

-- M4 — RPCs de API de Movimentação PDV Terceiro
CREATE OR REPLACE FUNCTION public.criar_pdv_api_key(
  p_nome     text,
  p_loja_ids integer[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_raw    text;
  v_prefix text;
  v_hash   text;
  v_id     uuid;
BEGIN
  IF NOT public.fn_pode_movimentar_pdv_admin() THEN
    RAISE EXCEPTION 'Acesso negado: apenas admin/master podem criar chaves PDV';
  END IF;

  IF trim(p_nome) = '' OR p_nome IS NULL THEN
    RAISE EXCEPTION 'nome não pode ser vazio';
  END IF;

  IF p_loja_ids IS NULL OR array_length(p_loja_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'loja_ids não pode ser vazio — informe ao menos uma loja';
  END IF;

  IF EXISTS (
    SELECT 1 FROM unnest(p_loja_ids) AS lid(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.lojas WHERE id = lid.id)
  ) THEN
    RAISE EXCEPTION 'Um ou mais loja_ids não existem em public.lojas';
  END IF;

  v_raw    := 'pdvk_' || encode(extensions.gen_random_bytes(24), 'hex');
  v_prefix := left(v_raw, 13);
  v_hash   := extensions.crypt(v_raw, extensions.gen_salt('bf', 10));

  INSERT INTO public.pdv_api_keys (nome, key_prefix, key_hash, loja_ids, created_by)
  VALUES (p_nome, v_prefix, v_hash, p_loja_ids, auth.uid())
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'ok',       true,
    'id',       v_id,
    'nome',     p_nome,
    'loja_ids', p_loja_ids,
    'api_key',  v_raw,
    'aviso',    'Guarde a chave agora — não é recuperável após este retorno'
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.criar_pdv_api_key(text, integer[]) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.criar_pdv_api_key(text, integer[]) TO authenticated;

CREATE OR REPLACE FUNCTION public.revogar_pdv_api_key(p_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_rows integer;
BEGIN
  IF NOT public.fn_pode_movimentar_pdv_admin() THEN
    RAISE EXCEPTION 'Acesso negado: apenas admin/master podem revogar chaves PDV';
  END IF;

  UPDATE public.pdv_api_keys
     SET ativo = false, revoked_at = now(), revoked_by = auth.uid()
   WHERE id = p_id
     AND revoked_at IS NULL;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows = 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Chave já revogada ou inexistente');
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', p_id);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.revogar_pdv_api_key(uuid) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.revogar_pdv_api_key(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.validar_pdv_api_key(p_key text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_rec record;
BEGIN
  SELECT id, loja_ids, key_hash, ativo, revoked_at
    INTO v_rec
    FROM public.pdv_api_keys
   WHERE key_prefix = left(p_key, 13);

  IF NOT FOUND OR NOT v_rec.ativo OR v_rec.revoked_at IS NOT NULL THEN
    PERFORM extensions.crypt(p_key, extensions.gen_salt('bf', 10));
    RETURN jsonb_build_object('ok', false);
  END IF;

  IF extensions.crypt(p_key, v_rec.key_hash) <> v_rec.key_hash THEN
    RETURN jsonb_build_object('ok', false);
  END IF;

  UPDATE public.pdv_api_keys SET last_used_at = now() WHERE id = v_rec.id;

  RETURN jsonb_build_object(
    'ok',         true,
    'api_key_id', v_rec.id,
    'loja_ids',   v_rec.loja_ids
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.validar_pdv_api_key(text) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.validar_pdv_api_key(text) TO service_role;

CREATE OR REPLACE FUNCTION public.consultar_etiqueta_pdv(p_uid text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_etq      jsonb;
  v_vencido  boolean;
  v_tipo_emb text;
  v_data_fab date;
BEGIN
  SELECT to_jsonb(t) INTO v_etq
    FROM public.view_etiqueta_timeline t
   WHERE t.uid = p_uid;

  IF NOT FOUND OR v_etq IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'UID não encontrado');
  END IF;

  SELECT eq.tipo_embalagem, l.data_fabricacao
    INTO v_tipo_emb, v_data_fab
    FROM public.etiquetas_qr eq
    LEFT JOIN public.lotes l ON l.id = eq.lote_id
   WHERE eq.uid = p_uid;

  v_vencido := (
    (v_etq->>'lote_validade_snapshot') IS NOT NULL
    AND (v_etq->>'lote_validade_snapshot')::date < CURRENT_DATE
  );

  RETURN jsonb_build_object(
    'ok',       true,
    'etiqueta', v_etq || jsonb_build_object(
                  'tipo_embalagem',       v_tipo_emb,
                  'lote_data_fabricacao', v_data_fab
                ),
    'vencido',  v_vencido
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.consultar_etiqueta_pdv(text) FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.consultar_etiqueta_pdv(text) TO service_role;

CREATE OR REPLACE FUNCTION public.movimentar_etiqueta_pdv(
  p_loja_id    integer,
  p_uid        text,
  p_tipo       text,
  p_api_key_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_key_rec    record;
  v_pid        integer;
  v_disp       numeric;
  v_interna    numeric;
  v_qty        numeric;
  v_val        date;
  v_status_pre text;
  v_loja_pre   integer;
  v_bip        jsonb;
  v_lote       uuid;
  v_ant        numeric;
  v_nova       numeric;
  v_usuario_id integer;
  v_alertas    jsonb;
  v_loja_nome  text;
BEGIN
  SELECT loja_ids, ativo, revoked_at
    INTO v_key_rec
    FROM public.pdv_api_keys
   WHERE id = p_api_key_id;

  IF NOT FOUND OR NOT v_key_rec.ativo OR v_key_rec.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'chave inválida ou revogada');
  END IF;

  IF NOT (p_loja_id = ANY(v_key_rec.loja_ids)) THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'loja fora do escopo da chave');
  END IF;

  IF p_tipo NOT IN ('entrada', 'saida') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'tipo deve ser "entrada" ou "saida"');
  END IF;

  SELECT id INTO v_usuario_id
    FROM public.usuarios
   WHERE username = 'pdv_integracao_sistema'
   LIMIT 1;

  IF v_usuario_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok',   false,
      'erro', 'Usuário-sistema PDV não encontrado; aplicar migration de seed (20260625140100)'
    );
  END IF;

  SELECT produto_master_id,
         COALESCE(quantidade_disponivel, 0),
         COALESCE(quantidade_interna, 0),
         lote_validade_snapshot,
         status,
         loja_atual_id
    INTO v_pid, v_disp, v_interna, v_val, v_status_pre, v_loja_pre
    FROM public.etiquetas_qr
   WHERE uid = p_uid;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',   false,
      'erro', 'Etiqueta não encontrada: ' || p_uid
    );
  END IF;

  v_bip := public.bipar_etiqueta(
    p_uid,
    p_tipo,
    jsonb_build_object(
      'loja_id',        p_loja_id,
      'referencia_tipo','pdv_externo',
      'referencia_id',  p_api_key_id::text
    )
  );

  IF v_bip IS NULL OR COALESCE((v_bip->>'ok')::boolean, false) = false THEN
    RETURN jsonb_build_object(
      'ok',        false,
      'duplicado', true,
      'erro',      COALESCE(
                     NULLIF(v_bip->>'erro', ''),
                     CASE WHEN p_tipo = 'entrada'
                          THEN 'Caixa já recebida nesta loja'
                          ELSE 'Caixa já em trânsito/saída registrada' END
                   ),
      'alertas', COALESCE(v_bip->'alertas', '[]'::jsonb)
    );
  END IF;

  v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0));
  IF v_qty IS NULL OR v_qty <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Caixa sem quantidade disponível');
  END IF;

  v_lote := public.resolver_lote_etiqueta(p_uid);
  IF v_lote IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote) THEN
    v_lote := NULL;
  END IF;

  SELECT COALESCE(quantidade_atual, 0)
    INTO v_ant
    FROM public.estoque
   WHERE produto_master_id = v_pid
     AND loja_id = p_loja_id;
  v_ant := COALESCE(v_ant, 0);

  IF p_tipo = 'entrada' THEN
    v_nova := v_ant + v_qty;
  ELSE
    v_nova := GREATEST(0, v_ant - v_qty);
  END IF;

  INSERT INTO public.movimentacoes (
    produto_master_id, tipo_movimentacao, quantidade,
    quantidade_anterior, quantidade_nova,
    motivo, observacoes, data_movimentacao,
    loja_id, lote_id, etiqueta_qr_uid, usuario_id
  ) VALUES (
    v_pid,
    p_tipo,
    v_qty,
    v_ant,
    v_nova,
    CASE WHEN p_tipo = 'entrada' THEN 'entrada_pdv_externo' ELSE 'saida_pdv_externo' END,
    'PDV terceiro — ' || p_tipo || ' caixa ' || p_uid,
    now(),
    p_loja_id,
    v_lote,
    p_uid,
    v_usuario_id
  );

  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid,
    tipo_evento,
    etapa,
    status_anterior,
    status_novo,
    loja_id,
    usuario_id,
    usuario_nome,
    referencia_tipo,
    referencia_id,
    metadata
  ) VALUES (
    p_uid,
    CASE WHEN p_tipo = 'entrada' THEN 'entrada_pdv_externo' ELSE 'saida_pdv_externo' END,
    p_tipo,
    v_bip->>'status_anterior',
    v_bip->>'status_novo',
    p_loja_id,
    NULL,
    'PDV Terceiro (integração)',
    'pdv_externo',
    p_api_key_id::text,
    jsonb_build_object(
      'quantidade',     v_qty,
      'saldo_anterior', v_ant,
      'saldo_novo',     v_nova,
      'lote_id',        v_lote
    )
  );

  v_alertas := COALESCE(v_bip->'alertas', '[]'::jsonb);

  IF p_tipo = 'entrada'
     AND v_status_pre = 'recebida'
     AND v_loja_pre IS DISTINCT FROM p_loja_id THEN
    SELECT nome INTO v_loja_nome
      FROM public.lojas
     WHERE id = v_loja_pre;
    v_alertas := v_alertas || to_jsonb(
      format(
        'caixa estava recebida em %s (loja %s) sem saída registrada',
        COALESCE(v_loja_nome, 'desconhecida'),
        v_loja_pre
      )
    );
  END IF;

  IF v_val IS NOT NULL AND v_val < CURRENT_DATE THEN
    v_alertas := v_alertas || to_jsonb(
      'LOTE VENCIDO em ' || to_char(v_val, 'DD/MM/YYYY')
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'tipo',           p_tipo,
    'uid',            p_uid,
    'loja_id',        p_loja_id,
    'quantidade',     v_qty,
    'saldo_anterior', v_ant,
    'saldo_novo',     v_nova,
    'status_novo',    v_bip->>'status_novo',
    'alertas',        v_alertas
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.movimentar_etiqueta_pdv(integer, text, text, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.movimentar_etiqueta_pdv(integer, text, text, uuid)
  TO service_role;

CREATE OR REPLACE FUNCTION public.movimentar_lote_pdv(
  p_loja_id    integer,
  p_uids       text[],
  p_tipo       text,
  p_api_key_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_ok         integer := 0;
  v_err        integer := 0;
  v_resultados jsonb   := '[]'::jsonb;
  v_uid        text;
  v_res        jsonb;
BEGIN
  IF p_uids IS NULL OR array_length(p_uids, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'p_uids não pode ser vazio');
  END IF;

  FOREACH v_uid IN ARRAY p_uids LOOP
    BEGIN
      v_res := public.movimentar_etiqueta_pdv(p_loja_id, v_uid, p_tipo, p_api_key_id);

      IF COALESCE((v_res->>'ok')::boolean, false) THEN
        v_ok := v_ok + 1;
      ELSE
        v_err := v_err + 1;
      END IF;

      v_resultados := v_resultados || (v_res || jsonb_build_object('uid', v_uid));

    EXCEPTION WHEN OTHERS THEN
      v_err        := v_err + 1;
      v_resultados := v_resultados || jsonb_build_object(
        'uid', v_uid,
        'ok',  false,
        'erro', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',          true,
    'processados', v_ok,
    'falhas',      v_err,
    'resultados',  v_resultados
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.movimentar_lote_pdv(integer, text[], text, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.movimentar_lote_pdv(integer, text[], text, uuid)
  TO service_role;

-- M5 — Requisição de PDV Externo
ALTER TABLE public.requisicoes
  ADD COLUMN IF NOT EXISTS origem            text NULL,
  ADD COLUMN IF NOT EXISTS pedido_externo_id text NULL,
  ADD COLUMN IF NOT EXISTS pdv_api_key_id    uuid NULL
    REFERENCES public.pdv_api_keys(id) ON DELETE SET NULL;

COMMENT ON COLUMN public.requisicoes.origem IS
  'Origem da requisição: NULL = interna (ERP), ''pdv_externo'' = criada via API PDV.';
COMMENT ON COLUMN public.requisicoes.pedido_externo_id IS
  'ID opaco do pedido no sistema PDV parceiro. Combinado com pdv_api_key_id '
  'provê idempotência: mesma chave + mesmo ID = retorna requisicao_id existente.';
COMMENT ON COLUMN public.requisicoes.pdv_api_key_id IS
  'FK rastreável para pdv_api_keys — identifica qual chave PDV criou a requisição. '
  'ON DELETE SET NULL: revogar a chave não apaga as requisições criadas por ela.';

CREATE UNIQUE INDEX IF NOT EXISTS uq_requisicoes_pdv_externo
  ON public.requisicoes (pdv_api_key_id, pedido_externo_id)
  WHERE pedido_externo_id IS NOT NULL;

CREATE OR REPLACE FUNCTION public.criar_requisicao_pdv(
  p_loja_id    integer,
  p_api_key_id uuid,
  p_payload    jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_key_rec            record;
  v_loja_nome          text;
  v_pedido_externo_id  text;
  v_data_receb         date;
  v_data_pedido        date;
  v_solicitante        text;
  v_subtitle           text;
  v_itens              jsonb;
  v_req_id             integer;
  v_req_existente      integer;
  v_nome_req           text;
  v_item               jsonb;
  v_nome_prod          text;
  v_nome_canonico      text;
  v_quantidade         numeric;
  v_obs                text;
  v_prod_id            integer;
  v_ordem              integer := 0;
  v_n_itens            integer := 0;
  v_dedupe_key         text;
  v_dedupe_vistos      text[]    := ARRAY[]::text[];
  v_itens_invalidos    integer[] := ARRAY[]::integer[];
  v_qtd_invalidas      jsonb     := '[]'::jsonb;
  v_itens_resolvidos   jsonb     := '[]'::jsonb;
BEGIN
  SELECT loja_ids, ativo, revoked_at
    INTO v_key_rec
    FROM public.pdv_api_keys
   WHERE id = p_api_key_id;

  IF NOT FOUND OR NOT v_key_rec.ativo OR v_key_rec.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'escopo',
                              'erro', 'chave inválida ou revogada');
  END IF;

  IF NOT (p_loja_id = ANY(v_key_rec.loja_ids)) THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'escopo',
                              'erro', 'loja fora do escopo da chave');
  END IF;

  SELECT nome INTO v_loja_nome
    FROM public.lojas
   WHERE id = p_loja_id;

  IF v_loja_nome IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'loja_invalida',
                              'erro', 'loja não encontrada no sistema');
  END IF;

  v_pedido_externo_id := NULLIF(trim(p_payload->>'pedido_externo_id'), '');
  v_data_receb        := COALESCE(
                           (NULLIF(trim(p_payload->>'data_recebimento'), ''))::date,
                           CURRENT_DATE
                         );
  v_data_pedido       := COALESCE(
                           (NULLIF(trim(p_payload->>'data_pedido'), ''))::date,
                           CURRENT_DATE
                         );
  v_solicitante       := COALESCE(NULLIF(trim(p_payload->>'solicitante'), ''), 'Pedido Certo');
  v_subtitle          := NULLIF(trim(p_payload->>'subtitle'), '');
  v_itens             := p_payload->'itens';

  IF v_itens IS NULL
     OR jsonb_typeof(v_itens) <> 'array'
     OR jsonb_array_length(v_itens) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'codigo', 'payload_invalido',
                              'erro', 'itens deve ser array não-vazio');
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_itens) LOOP
    v_prod_id    := NULLIF(v_item->>'produto_master_id', '')::integer;
    v_quantidade := NULLIF(v_item->>'quantidade', '')::numeric;
    v_obs        := NULLIF(trim(v_item->>'observacao'), '');

    IF v_quantidade IS NULL OR v_quantidade <= 0 THEN
      RETURN jsonb_build_object(
        'ok',     false,
        'codigo', 'quantidade_invalida',
        'erro',   'item com quantidade inválida (deve ser > 0); produto_master_id='
                  || COALESCE(v_prod_id::text, 'NULL')
                  || ', nome_produto=' || COALESCE(v_item->>'nome_produto', 'NULL')
      );
    END IF;

    IF v_prod_id IS NOT NULL THEN
      SELECT nome INTO v_nome_canonico
        FROM public.produtos_master
       WHERE id = v_prod_id
         AND ativo = true;

      IF NOT FOUND THEN
        v_itens_invalidos := v_itens_invalidos || v_prod_id;
        v_nome_canonico   := NULL;
      END IF;
    ELSE
      v_nome_canonico := NULLIF(trim(v_item->>'nome_produto'), '');
      IF v_nome_canonico IS NULL THEN
        RETURN jsonb_build_object(
          'ok',     false,
          'codigo', 'payload_invalido',
          'erro',   'item sem produto_master_id nem nome_produto — ao menos um é obrigatório'
        );
      END IF;
    END IF;

    IF ROUND(v_quantidade)::integer < 1 THEN
      v_qtd_invalidas := v_qtd_invalidas || jsonb_build_object(
        'produto_master_id', v_prod_id,
        'nome_produto',      v_nome_canonico,
        'quantidade_enviada', v_quantidade
      );
    END IF;

    v_itens_resolvidos := v_itens_resolvidos || jsonb_build_object(
      'nome_produto',      v_nome_canonico,
      'quantidade',        v_quantidade,
      'produto_master_id', v_prod_id,
      'observacao',        v_obs
    );
  END LOOP;

  IF array_length(v_itens_invalidos, 1) IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok',              false,
      'codigo',          'itens_invalidos',
      'erro',            'produto_master_id inválido(s) ou inativo(s)',
      'itens_invalidos', to_jsonb(v_itens_invalidos)
    );
  END IF;

  IF jsonb_array_length(v_qtd_invalidas) > 0 THEN
    RETURN jsonb_build_object(
      'ok',              false,
      'codigo',          'quantidade_invalida',
      'erro',            'quantidade(s) arredondam a 0 — use valores >= 0.5',
      'itens_invalidos', v_qtd_invalidas
    );
  END IF;

  IF v_pedido_externo_id IS NOT NULL THEN
    SELECT id INTO v_req_existente
      FROM public.requisicoes
     WHERE pdv_api_key_id    = p_api_key_id
       AND pedido_externo_id = v_pedido_externo_id
     LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'ok',            true,
        'duplicado',     true,
        'requisicao_id', v_req_existente
      );
    END IF;
  END IF;

  v_nome_req := 'Requisição - ' || v_loja_nome || ' - ' || to_char(v_data_receb, 'DD/MM/YY');

  BEGIN
    INSERT INTO public.requisicoes (
      nome, solicitante, preparador,
      loja_solicitante, loja_preparadora,
      data_pedido, data_recebimento,
      status, enqueued_at, user_id,
      subtitle, loja_destino_id,
      origem, pedido_externo_id, pdv_api_key_id
    ) VALUES (
      v_nome_req, v_solicitante, '',
      v_loja_nome, 'Fábrica',
      v_data_pedido, v_data_receb,
      'em_fila', now(), NULL,
      v_subtitle, p_loja_id,
      'pdv_externo', v_pedido_externo_id, p_api_key_id
    )
    RETURNING id INTO v_req_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_req_existente
      FROM public.requisicoes
     WHERE pdv_api_key_id    = p_api_key_id
       AND pedido_externo_id = v_pedido_externo_id
     LIMIT 1;
    RETURN jsonb_build_object(
      'ok',            true,
      'duplicado',     true,
      'requisicao_id', COALESCE(v_req_existente, -1)
    );
  END;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_itens_resolvidos) LOOP
    v_nome_prod  := v_item->>'nome_produto';
    v_quantidade := (v_item->>'quantidade')::numeric;
    v_obs        := v_item->>'observacao';
    v_prod_id    := NULLIF(v_item->>'produto_master_id', '')::integer;
    v_dedupe_key := lower(trim(v_nome_prod));

    IF v_dedupe_key = ANY(v_dedupe_vistos) THEN
      UPDATE public.requisicoes_itens
         SET quantidade_solicitada = quantidade_solicitada + ROUND(v_quantidade)::integer,
             observacao = CASE
               WHEN observacao IS NULL OR observacao = '' THEN v_obs
               WHEN v_obs IS NULL                         THEN observacao
               ELSE observacao || '; ' || v_obs
             END
       WHERE requisicao_id = v_req_id
         AND lower(nome_produto) = v_dedupe_key;
    ELSE
      INSERT INTO public.requisicoes_itens (
        requisicao_id, nome_produto,
        quantidade_solicitada, observacao,
        ordem, produto_id
      ) VALUES (
        v_req_id, v_nome_prod,
        ROUND(v_quantidade)::integer, v_obs,
        v_ordem, v_prod_id
      );
      v_dedupe_vistos := v_dedupe_vistos || v_dedupe_key;
      v_n_itens       := v_n_itens + 1;
      v_ordem         := v_ordem + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',               true,
    'requisicao_id',    v_req_id,
    'loja_solicitante', v_loja_nome,
    'itens_inseridos',  v_n_itens,
    'data_recebimento', v_data_receb
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.criar_requisicao_pdv(integer, uuid, jsonb)
  FROM PUBLIC, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.criar_requisicao_pdv(integer, uuid, jsonb)
  TO service_role;

SELECT
  public.validar_pdv_api_key('pdvk_3a5a1b4379b7cd7b859be1e906b2a7c5b7b63f48e91e54c7') AS validar_chave_real,
  public.validar_pdv_api_key('pdvk_falsa00000000000000000000000000000000000000000') AS validar_chave_falsa,
  public.consultar_etiqueta_pdv('f19caedd') AS consulta_etiqueta_real,
  public.consultar_etiqueta_pdv('uid_que_nao_existe') AS consulta_inexistente;

-- Ciclo completo de movimentação em transação com ROLLBACK (não persiste)
BEGIN;
CREATE TEMP TABLE _r(ord int, step text, res jsonb) ON COMMIT DROP;
INSERT INTO _r VALUES (1,'entrada_loja2',        public.movimentar_etiqueta_pdv(2,'f19caedd','entrada','e7067095-aacd-463a-a434-ea6f8efdabcd'));
INSERT INTO _r VALUES (2,'reentrada_loja2_dup',  public.movimentar_etiqueta_pdv(2,'f19caedd','entrada','e7067095-aacd-463a-a434-ea6f8efdabcd'));
INSERT INTO _r VALUES (3,'saida_loja2',          public.movimentar_etiqueta_pdv(2,'f19caedd','saida','e7067095-aacd-463a-a434-ea6f8efdabcd'));
INSERT INTO _r VALUES (4,'entrada_loja4',        public.movimentar_etiqueta_pdv(4,'f19caedd','entrada','ae809cb3-2695-46ba-812a-cef08c9c1336'));
INSERT INTO _r VALUES (5,'escopo_loja3_negado',  public.movimentar_etiqueta_pdv(3,'f19caedd','entrada','e7067095-aacd-463a-a434-ea6f8efdabcd'));
SELECT ord, step,
       res->>'ok'             AS ok,
       res->>'status_novo'    AS status_novo,
       res->>'saldo_anterior' AS saldo_ant,
       res->>'saldo_novo'     AS saldo_novo,
       res->>'duplicado'      AS dup,
       COALESCE(res->>'erro','') AS erro,
       res->'alertas'         AS alertas
  FROM _r ORDER BY ord;
ROLLBACK;

-- Testes de criar_requisicao_pdv em transação com ROLLBACK
BEGIN;
CREATE TEMP TABLE _q(ord int, step text, res jsonb) ON COMMIT DROP;
INSERT INTO _q VALUES (1,'criar_ok',        public.criar_requisicao_pdv(2,'e7067095-aacd-463a-a434-ea6f8efdabcd','{"pedido_externo_id":"TEST-PC-001","data_recebimento":"2026-07-02","itens":[{"produto_master_id":907,"quantidade":3},{"produto_master_id":908,"quantidade":2}]}'::jsonb));
INSERT INTO _q VALUES (2,'idempotente',     public.criar_requisicao_pdv(2,'e7067095-aacd-463a-a434-ea6f8efdabcd','{"pedido_externo_id":"TEST-PC-001","itens":[{"produto_master_id":907,"quantidade":3}]}'::jsonb));
INSERT INTO _q VALUES (3,'itens_invalidos', public.criar_requisicao_pdv(2,'e7067095-aacd-463a-a434-ea6f8efdabcd','{"itens":[{"produto_master_id":999999999,"quantidade":3}]}'::jsonb));
INSERT INTO _q VALUES (4,'escopo_loja3',    public.criar_requisicao_pdv(3,'e7067095-aacd-463a-a434-ea6f8efdabcd','{"itens":[{"produto_master_id":907,"quantidade":3}]}'::jsonb));
INSERT INTO _q VALUES (5,'qty_zero',        public.criar_requisicao_pdv(2,'e7067095-aacd-463a-a434-ea6f8efdabcd','{"itens":[{"produto_master_id":907,"quantidade":0.3}]}'::jsonb));
INSERT INTO _q VALUES (6,'dedupe_merge',    public.criar_requisicao_pdv(2,'e7067095-aacd-463a-a434-ea6f8efdabcd','{"pedido_externo_id":"TEST-PC-DEDUPE","itens":[{"produto_master_id":907,"quantidade":3},{"produto_master_id":907,"quantidade":4},{"nome_produto":"PORTA CASQUINHA PLASTICO (100 UNDS)","quantidade":1}]}'::jsonb));
SELECT
  (SELECT json_agg(json_build_object('ord',ord,'step',step,'ok',res->>'ok','codigo',res->>'codigo','req_id',res->>'requisicao_id','dup',res->>'duplicado','itens_inseridos',res->>'itens_inseridos','itens_invalidos',res->'itens_invalidos','loja',res->>'loja_solicitante','erro',res->>'erro') ORDER BY ord) FROM _q) AS resultados,
  (SELECT json_build_object('status',r.status,'loja_solicitante',r.loja_solicitante,'loja_preparadora',r.loja_preparadora,'origem',r.origem,'data_recebimento',r.data_recebimento,'nome',r.nome,
            'itens',(SELECT json_agg(json_build_object('nome',i.nome_produto,'qtd',i.quantidade_solicitada,'produto_id',i.produto_id) ORDER BY i.ordem) FROM public.requisicoes_itens i WHERE i.requisicao_id=r.id))
     FROM public.requisicoes r WHERE r.id = ((SELECT res->>'requisicao_id' FROM _q WHERE ord=1)::int)) AS card_criado,
  (SELECT json_agg(json_build_object('nome',i.nome_produto,'qtd',i.quantidade_solicitada) ORDER BY i.ordem)
     FROM public.requisicoes_itens i WHERE i.requisicao_id = ((SELECT res->>'requisicao_id' FROM _q WHERE ord=6)::int)) AS dedupe_itens;
ROLLBACK;

